<body>
    <div class="calendar-wrapper night-mode">
        <details class="details-calendar-button">
            <summary>
                <span class="calendar-icon">📅</span>
                日历
            </summary>
            <div class="calendar-content">
                <div class="calendar-header">
                    <div class="calendar-title">4月</div>
                    <div class="calendar-info">
                        <span id="year-display">年份 2015</span>
                        <button id="theme-toggle">切换到白天</button>
                    </div>
                </div>
                <div class="calendar-grid">
                    <div class="weekday">一</div>
                    <div class="weekday">二</div>
                    <div class="weekday">三</div>
                    <div class="weekday">四</div>
                    <div class="weekday">五</div>
                    <div class="weekday">六</div>
                    <div class="weekday">日</div>
                    <!-- 日期单元格由JavaScript动态生成 -->
                </div>
            </div>
        </details>
    </div>

    <!-- 日期详情模态框 -->
    <div id="day-modal" class="day-modal night-mode">
        <div class="modal-header">
            <div class="modal-title">日期详情</div>
            <div class="modal-close">&times;</div>
        </div>
        <div class="modal-body">
            <div class="modal-content"></div>
        </div>
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', function() {
            // 确保所有details元素在页面加载时折叠
            const detailsElements = document.querySelectorAll('details');
            detailsElements.forEach(function(details) {
                details.removeAttribute('open');
            });

            // 解析日历数据
            const calendarDataSource = document.getElementById('calendar-data-source');
            if (!calendarDataSource) {
                console.error('未找到日历数据源');
                return;
            }

            const calendarData = parseCalendarData(calendarDataSource.textContent);
            console.log('解析的日历数据:', calendarData);
            renderCalendar(calendarData);

            // 初始化主题
            initTheme();
        });

        // 解析日历数据
        function parseCalendarData(data) {
            // 新增：统一替换全角冒号为半角，支持混合格式
            data = data.replace(/：/g, ':');

            // 如果没有数据，使用默认数据
            if (!data || data.trim() === '') {
                console.log('使用默认日历数据');
                return {
                    year: 2015,
                    month: 4,
                    current_day: 15,
                    days: {
                        1: '开学典礼',
                        5: '数学考试',
                        10: '体育比赛',
                        15: '期中考试',
                        20: '家长会',
                        25: '艺术节'
                    }
                };
            }

            const lines = data.trim().split('\n');
            const calendarData = {
                year: 2015, // 默认值
                month: 4,   // 默认值
                current_day: new Date().getDate(),
                days: {}
            };

            let inDays = false;

            for (const line of lines) {
                const trimmedLine = line.trim(); // 关键修复：trim 每行以支持缩进数据
                if (trimmedLine.startsWith('year:')) {
                    calendarData.year = parseInt(trimmedLine.split(':')[1].trim());
                } else if (trimmedLine.startsWith('month:')) {
                    calendarData.month = parseInt(trimmedLine.split(':')[1].trim());
                } else if (trimmedLine.startsWith('current_day:')) {
                    calendarData.current_day = parseInt(trimmedLine.split(':')[1].trim());
                } else if (trimmedLine.startsWith('days:')) {
                    inDays = true;
                } else if (inDays && trimmedLine.includes(':')) {
                    const parts = trimmedLine.split(':');
                    if (parts.length >= 2) {
                        const day = parseInt(parts[0].trim());
                        const content = parts.slice(1).join(':').trim();
                        calendarData.days[day] = content;
                    }
                }
            }

            console.log('解析完成：year=' + calendarData.year + ', month=' + calendarData.month + ', current_day=' + calendarData.current_day + ', days_count=' + Object.keys(calendarData.days).length);
            return calendarData;
        }

        // 渲染日历
        function renderCalendar(calendarData) {
            const calendarGrid = document.querySelector('.calendar-grid');
            const calendarTitle = document.querySelector('.calendar-title');
            const yearDisplay = document.getElementById('year-display');
            const summary = document.querySelector('.details-calendar-button > summary');

            const year = calendarData.year;
            const month = calendarData.month;

            // 设置标题
            calendarTitle.textContent = `${month}月`;
            yearDisplay.textContent = `年份 ${year}`;

            // 更新折叠状态下的摘要文本
            summary.innerHTML = `<span class="calendar-icon">📅</span> ${year}年${month}月${calendarData.current_day}日`;

            // 清除旧的日期单元格（保留星期标题）
            const dayElements = calendarGrid.querySelectorAll('.day');
            dayElements.forEach(cell => cell.remove());

            // 计算当月总天数
            const daysInMonth = new Date(year, month, 0).getDate();

            // 计算当月第一天是星期几 (0=周一, 1=周二, ..., 6=周日)
            const firstDayOfMonth = new Date(year, month - 1, 1);
            const firstDayOfWeek = (firstDayOfMonth.getDay() + 6) % 7;

            // 填充日历开头的空白单元格
            for (let i = 0; i < firstDayOfWeek; i++) {
                const emptyCell = document.createElement('div');
                emptyCell.className = 'day empty';
                calendarGrid.appendChild(emptyCell);
            }

            // 创建并填充当月的每一天
            for (let day = 1; day <= daysInMonth; day++) {
                const dayElement = document.createElement('div');
                dayElement.className = 'day';
                if (day === calendarData.current_day) {
                    dayElement.classList.add('current-day');
                }

                // 添加日期数字
                const dayNumber = document.createElement('div');
                dayNumber.className = 'day-number';
                dayNumber.textContent = day;
                dayElement.appendChild(dayNumber);

                // 添加日期内容
                if (calendarData.days[day]) {
                    const dayContent = document.createElement('div');
                    dayContent.className = 'day-content';

                    const content = calendarData.days[day];
                    const contentItems = content.split(',').map(item => item.trim());

                    contentItems.forEach(text => {
                        if (text) {
                            const textElement = document.createElement('div');
                            textElement.className = 'normal-text';
                            textElement.textContent = text;
                            dayContent.appendChild(textElement);
                        }
                    });

                    dayElement.appendChild(dayContent);
                }

                // 添加双击事件监听器
                dayElement.addEventListener('dblclick', function(event) {
                    showDayDetails(day, calendarData.days[day] || '该日期无特殊内容。', event);
                });

                calendarGrid.appendChild(dayElement);
            }

            console.log(`渲染了 ${daysInMonth} 天的日历，从星期 ${firstDayOfWeek} 开始`);
        }

        // 初始化主题
        function initTheme() {
            const themeToggle = document.getElementById('theme-toggle');
            const calendarWrapper = document.querySelector('.calendar-wrapper');
            const dayModal = document.getElementById('day-modal');
            const calendarDetails = document.querySelector('.details-calendar-button');

            // 加载保存的主题偏好
            const savedTheme = localStorage.getItem('calendarTheme');
            if (savedTheme === 'day') {
                // 应用白天模式
                calendarWrapper.classList.remove('night-mode');
                calendarWrapper.classList.add('day-mode');
                dayModal.classList.remove('night-mode');
                dayModal.classList.add('day-mode');
                themeToggle.textContent = '切换到黑夜';
            } else {
                // 默认或保存为夜模式
                calendarWrapper.classList.add('night-mode');
                dayModal.classList.add('night-mode');
                themeToggle.textContent = '切换到白天';
            }

            // 监听日历折叠事件
            calendarDetails.addEventListener('toggle', function() {
                // 如果日历折叠，关闭所有打开的模态框
                if (!this.open) {
                    hideDayDetails();
                }
            });

            // 切换主题
            themeToggle.addEventListener('click', function() {
                if (calendarWrapper.classList.contains('night-mode')) {
                    // 切换到白天模式
                    calendarWrapper.classList.remove('night-mode');
                    calendarWrapper.classList.add('day-mode');
                    dayModal.classList.remove('night-mode');
                    dayModal.classList.add('day-mode');
                    this.textContent = '切换到黑夜';
                    localStorage.setItem('calendarTheme', 'day');
                } else {
                    // 切换到黑夜模式
                    calendarWrapper.classList.remove('day-mode');
                    calendarWrapper.classList.add('night-mode');
                    dayModal.classList.remove('day-mode');
                    dayModal.classList.add('night-mode');
                    this.textContent = '切换到白天';
                    localStorage.setItem('calendarTheme', 'night');
                }
            });
        }

        // 显示日期详情模态框
        function showDayDetails(day, content, event) {
            const modal = document.getElementById('day-modal');
            const modalContent = modal.querySelector('.modal-content');

            // 设置内容
            modalContent.textContent = `日期: ${day}\n\n内容:\n${content}`;

            // 显示模态框
            modal.style.display = 'block';

            // 计算位置 - 确保模态框在日历内且不超出边界
            const calendarRect = document.querySelector('.calendar-content').getBoundingClientRect();
            const modalRect = modal.getBoundingClientRect();

            // 尝试在双击位置附近显示模态框
            let top = event.clientY - calendarRect.top;
            let left = event.clientX - calendarRect.left;

            // 确保模态框不超出日历边界
            if (top + modalRect.height > calendarRect.height) {
                top = calendarRect.height - modalRect.height - 10;
            }
            if (left + modalRect.width > calendarRect.width) {
                left = calendarRect.width - modalRect.width - 10;
            }
            if (top < 10) top = 10;
            if (left < 10) left = 10;

            // 设置位置
            modal.style.top = top + 'px';
            modal.style.left = left + 'px';
        }

        // 隐藏日期详情模态框
        function hideDayDetails() {
            const modal = document.getElementById('day-modal');
            modal.style.display = 'none';
        }

        // 关闭模态框
        document.querySelector('.modal-close').addEventListener('click', function() {
            hideDayDetails();
        });

        // 点击模态框外部关闭
        document.addEventListener('click', function(event) {
            const modal = document.getElementById('day-modal');
            if (modal.style.display === 'block' && 
                !modal.contains(event.target) && 
                !event.target.classList.contains('day')) {
                hideDayDetails();
            }
        });

        // 按ESC键关闭模态框
        document.addEventListener('keydown', function(event) {
            if (event.key === 'Escape') {
                hideDayDetails();
            }
        });
    </script>
</body>
</html>
